import java.util.Scanner;

public class Main {
    static int m, n, p;
    static int[] dp = new int[505];
    static int[] cnt = new int[505];
    static int[][] dp2 = new int[505][505];
    static int[][] tot = new int[505][505];
    static int[] fac = new int[505];
    static int[] invfac = new int[505];

    static int mypow(int a, int b) {
        int ans = 1;
        while (b > 0) {
            if ((b & 1) == 1) {
                ans = (int) ((long) ans * a % p);
            }
            a = (int) ((long) a * a % p);
            b >>= 1;
        }
        return ans;
    }

    static int C(int n, int m) {
        return (int) ((long) fac[n] * invfac[m] % p * invfac[n - m] % p);
    }

    static int sum(int x) {
        return (int) ((long) x * (x + 1) / 2 % p);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextInt();
        m = sc.nextInt();
        p = sc.nextInt();

        fac[0] = 1;
        for (int i = 1; i <= 500; i++) {
            fac[i] = (int) ((long) fac[i - 1] * i % p);
        }
        invfac[500] = mypow(fac[500], p - 2);
        for (int i = 499; i >= 0; i--) {
            invfac[i] = (int) ((long) invfac[i + 1] * (i + 1) % p);
        }

        cnt[0] = 1;
        dp[0] = 0;
        cnt[1] = 2;
        dp[1] = 0;

        for (int i = 2; i <= m; i++) {
            for (int j = 1; j <= i; j++) {
                int zh = C(i - 1, j - 1);
                int tmp = (int) ((long) cnt[j - 1] * cnt[i - j] % p * zh % p);
                long tmpLong = tmp;
                long sumJMinus1 = sum(j - 1);
                long sumIminusJ = sum(i - j);
                long dpJMinus1 = dp[j - 1];
                long dpIminusJ = dp[i - j];
                long cntJMinus1 = cnt[j - 1];
                long cntIminusJ = cnt[i - j];

                // First update
                long val1 = (tmpLong * sumJMinus1) % p;
                long val2 = (zh * j) % p * ((dpJMinus1 * cntIminusJ + dpIminusJ * cntJMinus1) % p) % p;
                dp[i] = (int) ((dp[i] + val1 + val2) % p);
                cnt[i] = (int) ((cnt[i] + tmp * j) % p);

                // Second update
                long val3 = (tmpLong * sumIminusJ) % p;
                long val4 = (zh * (i - j + 1)) % p * ((dpJMinus1 * cntIminusJ + dpIminusJ * cntJMinus1) % p) % p;
                dp[i] = (int) ((dp[i] + val3 + val4) % p);
                cnt[i] = (int) ((cnt[i] + tmp * (i - j + 1)) % p);
            }
        }

        for (int i = 0; i <= n; i++) {
            for (int j = 0; j <= m; j++) {
                dp2[i][j] = 0;
                tot[i][j] = 0;
            }
        }
        dp2[0][0] = 0;
        tot[0][0] = 1;

        for (int i = 1; i <= n; i++) {
            for (int j = 0; j <= Math.min(m, i); j++) {
                dp2[i][j] = dp2[i - 1][j];
                tot[i][j] = tot[i - 1][j];
                for (int k = 1; k <= j; k++) {
                    if (k < i) {
                        int zh = C(j, k);
                        long val1 = ((long) dp[k] * zh % p * tot[i - k - 1][j - k]) % p;
                        long val2 = ((long) dp2[i - k - 1][j - k] * zh % p * cnt[k]) % p;
                        dp2[i][j] = (int) ((dp2[i][j] + val1 + val2) % p);
                        long val3 = ((long) cnt[k] * tot[i - k - 1][j - k]) % p * zh % p;
                        tot[i][j] = (int) ((tot[i][j] + val3) % p);
                    } else {
                        dp2[i][j] = (dp2[i][j] + dp[i]) % p;
                        tot[i][j] = (tot[i][j] + cnt[i]) % p;
                    }
                }
            }
        }

        System.out.println(dp2[n][m]);
        sc.close();
    }
}

